-- Generated by medallion from spec/tables/silver_orders.toml. Do not edit by hand.
-- Typed rows with expectations applied; the input to the change flow.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.orders_validated (
  order_id STRING COMMENT 'Order identifier',
  customer_id STRING COMMENT 'Customer identifier',
  status STRING COMMENT 'Order status, lower case',
  amount DECIMAL(18,2) COMMENT 'Order total',
  currency STRING COMMENT 'ISO currency code, upper case',
  order_ts TIMESTAMP COMMENT 'When the order was placed (UTC)',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  op STRING COMMENT 'Change operation, used for deletes only',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  CONSTRAINT order_id_present EXPECT (order_id IS NOT NULL AND length(order_id) > 0) ON VIOLATION DROP ROW,
  CONSTRAINT customer_id_present EXPECT (customer_id IS NOT NULL AND length(customer_id) > 0) ON VIOLATION DROP ROW,
  CONSTRAINT amount_valid EXPECT (amount IS NOT NULL AND amount >= 0) ON VIOLATION DROP ROW,
  CONSTRAINT order_ts_valid EXPECT (order_ts IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT updated_at_valid EXPECT (updated_at IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT currency_is_iso_length EXPECT (length(currency) = 3),
  CONSTRAINT status_known EXPECT (status IN ('new', 'completed', 'cancelled', 'refunded')),
  CONSTRAINT op_present EXPECT (op IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT op_known EXPECT (op IS NULL OR op IN ('I', 'U', 'D')) ON VIOLATION FAIL UPDATE
)
COMMENT 'Staging for silver.orders: typed rows that passed validation. Not for consumers.'
TBLPROPERTIES (
  'governance.owner' = 'sales-data',
  'governance.domain' = 'sales',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/silver_orders.toml',
  'governance.role' = 'staging'
)
AS SELECT
  try_cast(trim(order_id) AS STRING) AS order_id,
  try_cast(trim(customer_id) AS STRING) AS customer_id,
  try_cast(lower(trim(status)) AS STRING) AS status,
  try_cast(trim(amount) AS DECIMAL(18,2)) AS amount,
  try_cast(upper(trim(currency)) AS STRING) AS currency,
  try_cast(trim(order_ts) AS TIMESTAMP) AS order_ts,
  try_cast(trim(updated_at) AS TIMESTAMP) AS updated_at,
  try_cast(upper(trim(op)) AS STRING) AS op,
  _source_file,
  _ingested_at
FROM STREAM(${catalog}.bronze.orders);

-- The consumer-facing table. SCD type 1: one row per key.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.orders (
  order_id STRING COMMENT 'Order identifier',
  customer_id STRING COMMENT 'Customer identifier',
  status STRING COMMENT 'Order status, lower case',
  amount DECIMAL(18,2) COMMENT 'Order total',
  currency STRING COMMENT 'ISO currency code, upper case',
  order_ts TIMESTAMP COMMENT 'When the order was placed (UTC)',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row'
)
COMMENT 'Current state of each order: typed, validated and deduplicated by key. Bad rows go to the quarantine table.'
TBLPROPERTIES (
  'governance.owner' = 'sales-data',
  'governance.domain' = 'sales',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/silver_orders.toml',
  'governance.role' = 'serving'
);

CREATE FLOW silver_orders_apply_changes AS AUTO CDC INTO ${catalog}.silver.orders
FROM STREAM(${catalog}.silver.orders_validated)
KEYS (order_id)
APPLY AS DELETE WHEN op = 'D'
SEQUENCE BY updated_at
COLUMNS * EXCEPT (op)
STORED AS SCD TYPE 1;

-- Rows that failed a drop expectation, kept for investigation and replay.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.orders_quarantine (
  order_id STRING COMMENT 'Order identifier',
  customer_id STRING COMMENT 'Customer identifier',
  status STRING COMMENT 'Order status, lower case',
  amount DECIMAL(18,2) COMMENT 'Order total',
  currency STRING COMMENT 'ISO currency code, upper case',
  order_ts TIMESTAMP COMMENT 'When the order was placed (UTC)',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  op STRING COMMENT 'Change operation, used for deletes only',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  failed_rules ARRAY<STRING> COMMENT 'Names of the drop expectations this row failed'
)
COMMENT 'Rows from bronze.orders that failed a drop expectation for silver.orders, with the rules they failed.'
TBLPROPERTIES (
  'governance.owner' = 'sales-data',
  'governance.domain' = 'sales',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/silver_orders.toml',
  'governance.role' = 'quarantine'
)
AS SELECT
  *,
  filter(array(
    CASE WHEN coalesce(order_id IS NOT NULL AND length(order_id) > 0, false) THEN NULL ELSE 'order_id_present' END,
    CASE WHEN coalesce(customer_id IS NOT NULL AND length(customer_id) > 0, false) THEN NULL ELSE 'customer_id_present' END,
    CASE WHEN coalesce(amount IS NOT NULL AND amount >= 0, false) THEN NULL ELSE 'amount_valid' END,
    CASE WHEN coalesce(order_ts IS NOT NULL, false) THEN NULL ELSE 'order_ts_valid' END,
    CASE WHEN coalesce(updated_at IS NOT NULL, false) THEN NULL ELSE 'updated_at_valid' END,
    CASE WHEN coalesce(op IS NOT NULL, false) THEN NULL ELSE 'op_present' END
  ), x -> x IS NOT NULL) AS failed_rules
FROM (
  SELECT
    try_cast(trim(order_id) AS STRING) AS order_id,
    try_cast(trim(customer_id) AS STRING) AS customer_id,
    try_cast(lower(trim(status)) AS STRING) AS status,
    try_cast(trim(amount) AS DECIMAL(18,2)) AS amount,
    try_cast(upper(trim(currency)) AS STRING) AS currency,
    try_cast(trim(order_ts) AS TIMESTAMP) AS order_ts,
    try_cast(trim(updated_at) AS TIMESTAMP) AS updated_at,
    try_cast(upper(trim(op)) AS STRING) AS op,
    _source_file,
    _ingested_at
  FROM STREAM(${catalog}.bronze.orders)
)
WHERE NOT coalesce((order_id IS NOT NULL AND length(order_id) > 0) AND (customer_id IS NOT NULL AND length(customer_id) > 0) AND (amount IS NOT NULL AND amount >= 0) AND (order_ts IS NOT NULL) AND (updated_at IS NOT NULL) AND (op IS NOT NULL), false);
